import {React, useState, useEffect} from "react";
import {useStateMachine} from "little-state-machine";
import {Link} from "react-router-dom";
import './theme.css';
import './HomePage.css';
import {languages, locale_text} from "./lang";

export function HomePage({setGlobalLanguage}) {
    const {actions, state} = useStateMachine({
        changeLanguage: (state, payload) => {
            console.log(state, payload)
            return ({...state, 'language': payload});
        }
    });

    const [currentLanguageState, setLanguageState] = useState(state['language']);
    const lang = currentLanguageState;

    // Floating dots effect
    useEffect(() => {
        const createFloatingDots = () => {
            const container = document.querySelector('.floating-dots-container');
            if (!container) return;

            // Soft nature-inspired colors
            const colors = [
                '#A8D5A8', // Soft green
                '#B8E6B8', // Light green
                '#C8F7C8', // Very light green
                '#E8F5E8', // Pale green
                '#F0F8F0', // Almost white green
                '#D4E5D4', // Muted green
                '#9FCC9F', // Medium green
                '#87B987'  // Darker soft green
            ];

            const sizes = ['small', 'medium', 'large'];

            const createDot = () => {
                const dot = document.createElement('div');
                dot.className = `floating-dot ${sizes[Math.floor(Math.random() * sizes.length)]}`;

                // Random color
                const color = colors[Math.floor(Math.random() * colors.length)];
                dot.style.backgroundColor = color;

                // Random horizontal position
                const leftPos = Math.random() * 100;
                dot.style.left = leftPos + '%';

                // Random horizontal drift during animation
                const drift = (Math.random() - 0.5) * 100; // -50px to +50px
                dot.style.setProperty('--drift', drift + 'px');

                // Random animation duration (8-20 seconds)
                const duration = 8 + Math.random() * 12;
                dot.style.animationDuration = duration + 's';

                // Random delay before starting
                const delay = Math.random() * 5;
                dot.style.animationDelay = delay + 's';

                container.appendChild(dot);

                // Remove dot after animation completes
                setTimeout(() => {
                    if (dot.parentNode) {
                        dot.parentNode.removeChild(dot);
                    }
                }, (duration + delay) * 1000);
            };

            // Create initial dots
            for (let i = 0; i < 8; i++) {
                setTimeout(() => createDot(), i * 500);
            }

            // Continue creating dots periodically
            const interval = setInterval(() => {
                createDot();
            }, 2000 + Math.random() * 3000); // Every 2-5 seconds

            // Cleanup function
            return () => {
                clearInterval(interval);
                if (container) {
                    container.innerHTML = '';
                }
            };
        };

        const cleanup = createFloatingDots();
        return cleanup;
    }, []);

    return (
        <div className="page-container">
            {/* Floating dots container */}
            <div className="floating-dots-container"></div>

            {/* Header with logo, title and language options */}
            <header className="header-container">
                {/* Main Title */}
                <h1 className="main-title">
                    Feeling Nature Seoul
                </h1>

                {/* Language Navigation */}
                <nav>
                    <ul className="navbar">
                        {
                            Object.entries(languages).map(([key, value]) => {
                                const isSelected = (lang === value);
                                const isSelectedClass = isSelected ? "nav-li-selected" : "";
                                const targetLanguage = value;
                                const setLanguage = () => {
                                    actions.changeLanguage(targetLanguage);
                                    setLanguageState(targetLanguage);
                                    setGlobalLanguage(targetLanguage);
                                };

                                return (
                                    <li 
                                        key={value} 
                                        className={isSelectedClass}
                                        onClick={setLanguage}
                                    >
                                        <a>{key}</a>
                                    </li>
                                )
                            })
                        }
                    </ul>
                </nav>
            </header>

            {/* Header Logo */}
            <div className="header-logo">
                <a 
                    href="https://senseable.mit.edu/feeling-nature/" 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="header-logo-link"
                >
                    <img 
                        src="/FN-logo3.gif" 
                        alt="Senseable City Lab" 
                        className="header-logo-image"
                    />
                </a>
            </div>

            {/* Main content */}
            <div className="content-wrapper">
                <h2 className="subtitle">
                    {locale_text(lang, 'home-page-subtitle')}
                </h2>

                <p className="description-text">
                    {locale_text(lang, 'home-page-description')}
                </p>

                <Link to="/surveycity">
                    <button className="homepage-button">
                        {locale_text(lang, 'home-page-button-start-survey')}
                    </button>
                </Link>
            </div>

            {/* Footer with clickable logos */}
            <footer className="footer-container">
                <div className="logo-container">
                    <a 
                        href="https://senseable.mit.edu/" 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="footer-logo-link"
                    >
                        <img className="home-org-icon" src="/org-mit.png" alt="MIT" />
                    </a>
                    <a 
                        href="https://www.kaist.ac.kr/en/" 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="footer-logo-link"
                    >
                        <img className="home-org-icon" src="/org-kaist.svg" alt="KAIST" />
                    </a>
                </div>
            </footer>
        </div>
    );
}
